/**
 * A card with the "type your own" box the agent adds under its choices (an
 * AskField in the root's `answer` slot, as ask_card_surface builds it).
 */
export const withAnswer = (card: unknown, placeholder: string) => {
  const { version, createSurface } = card as {
    version: string;
    createSurface: { components: { id: string }[] };
  };
  const [root, ...rest] = createSurface.components;
  const text = { '@path': '/reply/text' };
  return {
    version,
    createSurface: {
      ...createSurface,
      components: [
        { ...root, answer: ['answer'] },
        ...rest,
        {
          id: 'answer',
          component: 'AskField',
          placeholder,
          value: text,
          action: { event: { name: 'type_answer', userMessage: text } },
        },
      ],
    },
  };
};

